import {build} from 'esbuild';
import {readFile,writeFile} from 'node:fs/promises';
import {dirname,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const root=dirname(fileURLToPath(import.meta.url));
const result=await build({
  absWorkingDir:root,entryPoints:['code-editor.js'],outfile:'../web/code-editor.js',
  bundle:true,minify:true,format:'esm',target:['es2022'],metafile:true,legalComments:'inline',
  // Escape whitespace inside language snippet templates in the generated file.
  supported:{'template-literal':false},
  banner:{js:'// Generated by frontend/build.mjs. Dependency licenses: /editor-licenses.txt'},
});
const packages=new Set();
for(const input of Object.keys(result.metafile.inputs)) {
  const match=input.replaceAll('\\','/').match(/node_modules\/((?:@[^/]+\/)?[^/]+)/);
  if(match)packages.add(match[1]);
}
let notices='Bundled editor dependencies. Rebuild: cd go/testbench/frontend && npm ci && npm run build\n';
for(const name of [...packages].sort()) {
  const directory=resolve(root,'node_modules',name);
  const meta=JSON.parse(await readFile(resolve(directory,'package.json'),'utf8'));
  let license;
  for(const filename of ['LICENSE','LICENSE.md','LICENSE.txt']) {
    try {license=await readFile(resolve(directory,filename),'utf8');break;}catch(error){if(error.code!=='ENOENT')throw error;}
  }
  if(!license)throw new Error(`Missing license for ${name}`);
  notices+=`\n--- ${name}@${meta.version} (${meta.license}) ---\n${license}\n`;
}
await writeFile(resolve(root,'../web/editor-licenses.txt'),notices.trimEnd()+'\n');
